                )
        title_to_document: dict[str, str] = {}
        for note in _note_documents(human_root):
            content = str(note["content"])
            connection.execute(
                "INSERT INTO documents VALUES(?,?,?,?,?,?,?,?)",
                (note["id"], note["kind"], note["title"], note["tag"], note["relative_path"], None, content, estimated_tokens(content)),
            )
            title_to_document[note["title"]] = note["id"]
            chunks = _markdown_sections(content)
            for ordinal, (heading, section_content) in enumerate(chunks):
                section_id = f"{note['id']}:{ordinal}"
                connection.execute(
                    "INSERT INTO sections VALUES(?,?,?,?,?,?,?,?,?)",
                    (section_id, note["id"], ordinal, heading, section_content, estimated_tokens(section_content), None, None, None),
                )
                connection.execute("INSERT INTO section_fts VALUES(?,?,?,?,?)", (section_id, note["id"], heading, section_content, ""))
            for target_title in note["links"]:
                connection.execute(
                    "INSERT OR IGNORE INTO document_links VALUES(?,?,?,?)",
                    (note["id"], None, target_title, "wikilink"),
                )
        overlay = output / "workspace-meta/working-overlay.json"
        if overlay.is_file():
            value = json_load(overlay)
            for path in value.get("changed_paths", []):
                connection.execute("INSERT OR REPLACE INTO workspace_changes VALUES(?,?,?)", (path, "changed", json.dumps(value, ensure_ascii=False, sort_keys=True)))
            for path in value.get("untracked_paths", []):
                connection.execute("INSERT OR REPLACE INTO workspace_changes VALUES(?,?,?)", (path, "untracked", json.dumps(value, ensure_ascii=False, sort_keys=True)))
        connection.commit()
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        if integrity != "ok" or foreign_keys:
            raise CkbError(f"machine knowledge integrity failed: integrity={integrity}; foreign_keys={foreign_keys}")
    finally:
        connection.close()
    temporary.replace(target)
    return audit_machine_knowledge(output, graph)


def _markdown_sections(content: str) -> list[tuple[str, str]]:
    result: list[tuple[str, str]] = []
    heading = "正文"
    buffer: list[str] = []
    in_fence = False
    for line in content.replace("\r\n", "\n").splitlines():
        if line.lstrip().startswith(("```", "~~~")):
            in_fence = not in_fence
        match = None if in_fence else re.match(r"^#{1,6}\s+(.+?)\s*$", line)
        if match:
            if any(value.strip() for value in buffer):
                result.append((heading, "\n".join(buffer).strip()))
            heading = match.group(1).strip()
            buffer = []
        else:
            buffer.append(line)
    if any(value.strip() for value in buffer):
        result.append((heading, "\n".join(buffer).strip()))
    return result or [("正文", content.strip())]


def audit_machine_knowledge(output: Path, graph: dict[str, Any] | None = None) -> dict[str, Any]:
    output = output.resolve()
    graph = graph or json_load(output / "graph.json")
    path = output / MACHINE_PATH
    errors: list[dict[str, Any]] = []
    if not path.is_file():
        return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "failed", "path": str(path), "errors": [{"reason": "machine-sqlite-missing"}]}
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        counts = {
            name: connection.execute(f"SELECT count(*) FROM {name}").fetchone()[0]
            for name in ("files", "entities", "source_ranges", "relations", "reviews", "documents", "sections", "human_projection", "workspace_changes")
        }
        meta = dict(connection.execute("SELECT key,value FROM meta"))
        language_errors = [
            row[0]
            for row in connection.execute(
                """
                SELECT entity_id FROM entities
                WHERE (classification='appendix' AND description_zh NOT GLOB '*[一-龥]*')
                   OR (classification<>'appendix' AND (meaning_zh NOT GLOB '*[一-龥]*' OR role_zh NOT GLOB '*[一-龥]*' OR change_when_zh NOT GLOB '*[一-龥]*'))
                   OR evidence_note NOT GLOB '*[一-龥]*'
                """
            )
        ]
        fts_counts = {
            "entity_fts": connection.execute("SELECT count(*) FROM entity_fts").fetchone()[0],
            "section_fts": connection.execute("SELECT count(*) FROM section_fts").fetchone()[0],
            "source_fts": connection.execute("SELECT count(*) FROM source_fts").fetchone()[0],
        }
    finally:
        connection.close()
    expected_entities = len(graph.get("entities", []))
    expected_files = len([entity for entity in graph.get("entities", []) if entity.get("kind") == "file"])
    expected_relations = len(graph.get("links", []))
    if integrity != "ok": errors.append({"reason": "sqlite-integrity", "detail": integrity})
    if foreign_keys: errors.append({"reason": "foreign-key-errors", "detail": foreign_keys})
    for name, actual, expected in (
        ("entities", counts["entities"], expected_entities),
        ("source_ranges", counts["source_ranges"], expected_entities),
        ("reviews", counts["reviews"], expected_entities),
        ("human_projection", counts["human_projection"], expected_entities),
        ("files", counts["files"], expected_files),
        ("relations", counts["relations"], expected_relations),
        ("entity_fts", fts_counts["entity_fts"], expected_entities),
        ("source_fts", fts_counts["source_fts"], expected_files),
    ):
        if actual != expected:
            errors.append({"reason": f"{name}-count-mismatch", "actual": actual, "expected": expected})
    if fts_counts["section_fts"] != counts["sections"]:
        errors.append({"reason": "section-fts-count-mismatch", "actual": fts_counts["section_fts"], "expected": counts["sections"]})
    if language_errors:
        errors.append({"reason": "chinese-description-contract", "entities": language_errors})
    if meta.get("schema_version") != str(MACHINE_SCHEMA_VERSION) or meta.get("status") != "ready":
        errors.append({"reason": "machine-meta-incompatible", "meta": meta})
    result = {
        "schema_version": MACHINE_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "path": str(path.resolve()),
        "integrity": integrity,
        "counts": counts,
        "fts_counts": fts_counts,
        "language_contract": meta.get("language_contract"),
        "retrieval": meta.get("retrieval"),
        "errors": errors,
    }
    json_write(output / "machine/audit.json", result)
    return result


def _adjacency(connection: sqlite3.Connection) -> tuple[dict[str, list[tuple[str, float, str]]], dict[str, int]]:
    adjacency: dict[str, list[tuple[str, float, str]]] = defaultdict(list)
    degree: dict[str, int] = defaultdict(int)
    for source, target, relation, weight in connection.execute("SELECT source_entity_id,target_entity_id,relation,weight FROM relations ORDER BY relation_id"):
        adjacency[source].append((target, float(weight), relation))
        adjacency[target].append((source, float(weight) * 0.72, relation))
        degree[source] += 1
        degree[target] += 1
    for values in adjacency.values():
        values.sort(key=lambda item: (item[0], item[2]))
    return adjacency, degree


def _fast_graph_scores(
    seeds: list[str],
    seed_scores: dict[str, float],
    adjacency: dict[str, list[tuple[str, float, str]]],
    degree: dict[str, int],
) -> dict[str, float]:
    result: dict[str, float] = defaultdict(float)
    frontier = {seed: seed_scores[seed] for seed in seeds}
    for depth in (1, 2):
        next_frontier: dict[str, float] = defaultdict(float)
        for source in sorted(frontier):
            source_score = frontier[source]
            outgoing = adjacency.get(source, [])
            total = sum(weight for _target, weight, _relation in outgoing) or 1.0
            for target, weight, _relation in outgoing:
                contribution = source_score * (0.28 if depth == 1 else 0.10) * weight / total / math.sqrt(max(1, degree.get(target, 1)))
                if contribution > next_frontier[target]:
                    next_frontier[target] = contribution
                result[target] += contribution
        frontier = next_frontier
    return dict(result)


def _deterministic_ppr(
    seeds: list[str],
    seed_scores: dict[str, float],
    adjacency: dict[str, list[tuple[str, float, str]]],
    degree: dict[str, int],
    iterations: int = 24,
    restart: float = 0.22,
) -> dict[str, float]:
    if not seeds:
        return {}
    total_seed = sum(max(seed_scores[value], 0.0) for value in seeds) or float(len(seeds))
    personalization = {value: max(seed_scores[value], 0.0) / total_seed for value in seeds}
    scores = dict(personalization)
    for _ in range(iterations):
        updated: dict[str, float] = defaultdict(float)
        dangling = 0.0
        for source in sorted(scores):
            source_score = scores[source]
            outgoing = adjacency.get(source, [])
            if not outgoing:
                dangling += source_score
                continue
            normalized = [
                (target, weight / math.sqrt(max(1, degree.get(target, 1))))
                for target, weight, _relation in outgoing
            ]
            total = sum(weight for _target, weight in normalized) or 1.0
            for target, weight in normalized:
                updated[target] += (1.0 - restart) * source_score * weight / total
        for seed, probability in personalization.items():
            updated[seed] += restart * probability + (1.0 - restart) * dangling * probability
        scores = {key: updated[key] for key in sorted(updated)}
    return scores


def _next_pack_path(output: Path) -> tuple[Path, Path]:
    directory = output / "machine/agent-packs"
    directory.mkdir(parents=True, exist_ok=True)
    prefix = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d-%H%M%S-%f")
    for counter in range(1, 1000):
        markdown = directory / f"pack-{prefix}-{counter:02d}.md"
        record = markdown.with_suffix(".json")
        if not markdown.exists() and not record.exists():
            return markdown, record
    raise CkbError("machine pack name space is exhausted")


def _sql_placeholders(values: Iterable[Any]) -> str:
    items = list(values)
    if not items:
        raise CkbError("SQL placeholder list must not be empty")
    return ",".join("?" for _ in items)


def _utf8_prefix(value: str, maximum_bytes: int) -> str:
    if maximum_bytes <= 0:
        return ""
    data = value.encode("utf-8")[:maximum_bytes]
    while data:
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as exc:
            data = data[: exc.start]
    return ""


def _bulk_entity_context(
    connection: sqlite3.Connection,
    entity_ids: list[str],
) -> tuple[dict[str, sqlite3.Row], dict[str, list[sqlite3.Row]]]:
    if not entity_ids:
        return {}, {}
    placeholders = _sql_placeholders(entity_ids)
    entity_rows = {
        row["entity_id"]: row
        for row in connection.execute(
            f"SELECT e.*,r.start_line,r.end_line,h.title AS human_title,h.page_file,h.display_mode "
            f"FROM entities e JOIN source_ranges r USING(entity_id) LEFT JOIN human_projection h USING(entity_id) "
            f"WHERE e.entity_id IN ({placeholders})",
            entity_ids,
        )
    }
    sections: dict[str, list[sqlite3.Row]] = defaultdict(list)
    for row in connection.execute(
        f"SELECT d.source_entity_id,s.* FROM sections s JOIN documents d ON d.document_id=s.document_id "
        f"WHERE d.source_entity_id IN ({placeholders}) ORDER BY d.source_entity_id,s.ordinal",
        entity_ids,
    ):
        sections[row["source_entity_id"]].append(row)
    return entity_rows, sections


def _diverse_candidates(
    ordered_ids: list[str],
    entity_rows: dict[str, sqlite3.Row],
    limit: int,
) -> list[str]:
    selected: list[str] = []
    selected_set: set[str] = set()
    paths: set[str] = set()
    for entity_id in ordered_ids:
        row = entity_rows.get(entity_id)
        if row is None or row["source_path"] in paths:
            continue
        selected.append(entity_id)
        selected_set.add(entity_id)
        paths.add(row["source_path"])
        if len(selected) >= limit:
            return selected
    for entity_id in ordered_ids:
        if entity_id in selected_set or entity_id not in entity_rows:
            continue
        selected.append(entity_id)
        if len(selected) >= limit:
            break
    return selected


def _compact_entity_block(
    entity: sqlite3.Row,
    sections: list[sqlite3.Row],
    section_scores: dict[str, float],
    reason_values: list[str],
    source_link: str,
    allocation_bytes: int,
    profile: str,
) -> tuple[str, list[str]]:
    unique_reasons = list(dict.fromkeys(reason_values))[:4]
    reason_text = "；".join(unique_reasons)
    lines = [
        f"## {entity['qualified_name']}",
        "",
        f"选择原因：{reason_text}",
        "",
        f"源码：{source_link}",
        "",
    ]
    if entity["human_title"]:
        lines.extend([f"人类知识页：[[{entity['human_title']}]]（{entity['display_mode']}）", ""])
    mandatory = "\n".join(lines).rstrip() + "\n"
    if len(mandatory.encode("utf-8")) > allocation_bytes:
        short_reason = "；".join(unique_reasons[:2])
        mandatory = (
            f"## {entity['qualified_name']}\n\n"
            f"选择原因：{short_reason}\n\n"
            f"源码：{source_link}\n"
        )
    remaining = max(0, allocation_bytes - len(mandatory.encode("utf-8")) - 2)
    ranked = sorted(
        sections,
        key=lambda row: (-section_scores.get(row["section_id"], 0.0), row["ordinal"]),
    )[: (4 if profile == "fast" else 7)]
    chunks: list[str] = []
    included: list[str] = []
    for section in ranked:
        prefix = f"\n### {section['heading']}\n\n"
        prefix_bytes = len(prefix.encode("utf-8"))
        if prefix_bytes + 12 > remaining:
            break
        content = str(section["content"]).strip()
        available = remaining - prefix_bytes
        if len(content.encode("utf-8")) > available:
            content = _utf8_prefix(content, max(0, available - len("\n\n> 本节已按预算截断。".encode("utf-8")))).rstrip()
            content += "\n\n> 本节已按预算截断。"
        chunk = prefix + content + "\n"
        encoded = len(chunk.encode("utf-8"))
        if encoded > remaining:
            break
        chunks.append(chunk)
        included.append(section["heading"])
        remaining -= encoded
    block = mandatory + "".join(chunks)
    if len(block.encode("utf-8")) > allocation_bytes:
        block = _utf8_prefix(block, allocation_bytes).rstrip() + "\n"
    return block.rstrip() + "\n\n", included


def _static_retrieval_key(database: Path, output: Path) -> str:
    """Return a cheap fingerprint for immutable retrieval data.

    ``retrieve`` already receives normalized output/database paths, so resolving
    them again would add filesystem work to every warm query. Size and mtime
    invalidate a replaced machine database; the opener mtime invalidates cached
    source URIs when the source-view configuration changes.
    """

    openers_path = output / "local-openers.json"
    database_stat = database.stat()
    opener_mtime = openers_path.stat().st_mtime_ns if openers_path.is_file() else 0
    return f"{database.absolute()}:{database_stat.st_size}:{database_stat.st_mtime_ns}:{opener_mtime}"


def _static_retrieval_context(
    connection: sqlite3.Connection,
    output: Path,
    entity_columns: set[str],
    key: str,
) -> dict[str, Any] | None:
    required_columns = {
        "entity_id",
        "kind",
        "name",
        "qualified_name",
        "source_path",
        "meaning_zh",
        "role_zh",
        "change_when_zh",
        "description_zh",
    }
    tables = {
        str(row[0])
        for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")
    }
    if not required_columns.issubset(entity_columns) or not {"source_ranges", "human_projection", "sections", "documents"}.issubset(tables):
        return None
    metadata_rows = [
        dict(row)
        for row in connection.execute(
            "SELECT entity_id,kind,name,qualified_name,source_path,meaning_zh,role_zh,change_when_zh,description_zh FROM entities"
        )
    ]
    entity_rows = {
        row["entity_id"]: dict(row)
        for row in connection.execute(
            "SELECT e.*,r.start_line,r.end_line,h.title AS human_title,h.page_file,h.display_mode "
            "FROM entities e JOIN source_ranges r USING(entity_id) LEFT JOIN human_projection h USING(entity_id)"
        )
    }
    sections: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in connection.execute(
        "SELECT d.source_entity_id,s.* FROM sections s JOIN documents d ON d.document_id=s.document_id "
        "WHERE d.source_entity_id IS NOT NULL ORDER BY d.source_entity_id,s.ordinal"
    ):
        sections[row["source_entity_id"]].append(dict(row))
    adjacency, degree = _adjacency(connection)
    value = {
        "metadata_rows": metadata_rows,
        "entity_rows": entity_rows,
        "sections": dict(sections),
        "adjacency": adjacency,
        "degree": degree,
        "linker": SourceLinkRenderer(_openers(output), trusted_relative_paths=True),
        "entity_columns": entity_columns,
    }
    _RETRIEVAL_STATIC_CACHE.clear()
    _RETRIEVAL_STATIC_CACHE[key] = value
    return value


def _openers(output: Path) -> dict[str, Any]:
    path = output / "local-openers.json"
    if path.is_file():
        return json_load(path)
    state = json_load(output / "state.json")
    return {
        "source_editor": "vscode",
        "working_repo_root": state["repository"]["root"],
        "baseline_snapshot_root": (state.get("source_snapshot") or {}).get("root"),
        "source_view": "working",
        "show_source_range": True,
        "custom_template": None,
    }


def retrieve_machine(
    output: Path,
    question: str,
    budget: int = 1500,
    entity_limit: int = 8,
    profile: str = "fast",
) -> dict[str, Any]:
    if profile not in {"fast", "precise"}:
        raise CkbError("machine retrieval profile must be fast or precise")
    if budget < 200:
        raise CkbError("retrieve budget must be at least 200")
    path = output / MACHINE_PATH
    if not path.is_file():
        raise CkbError("machine knowledge is missing; run finalize or machine-reindex")
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    scores: dict[str, float] = defaultdict(float)
    breakdown: dict[str, dict[str, float]] = defaultdict(lambda: defaultdict(float))
    reasons: dict[str, list[str]] = defaultdict(list)
    section_scores: dict[str, float] = {}
    terms = search_terms(question)
    anchors = explicit_anchors(question)
    from .automation import search_automation

    automation_intent = bool(
        re.search(
            r"(?:会话自动化|会话记录|对话记录|修改记录|实验记录|踩坑记录|待审阅|自动化记录|session|conversation|pending review)",
            question,
            flags=re.IGNORECASE,
        )
    )
    automation_rows = search_automation(output, question, 8) if automation_intent else []

    def add(entity_id: str, value: float, stage: str, reason: str) -> None:
        scores[entity_id] += value
        breakdown[entity_id][stage] += value
        reasons[entity_id].append(reason)

    try:
        exact_rows = connection.execute(
            "SELECT entity_id,name,qualified_name,source_path FROM entities WHERE name=? COLLATE NOCASE OR qualified_name=? COLLATE NOCASE OR source_path=? COLLATE NOCASE",
            (question, question, question),
        ).fetchall()
        for row in exact_rows:
            add(row["entity_id"], 1000.0, "exact", f"精确命中 `{row['qualified_name']}`")
        if anchors:
            placeholders = _sql_placeholders(anchors)
            for row in connection.execute(
                f"SELECT entity_id,name,qualified_name FROM entities "
                f"WHERE name COLLATE NOCASE IN ({placeholders}) OR qualified_name COLLATE NOCASE IN ({placeholders}) "
                "ORDER BY entity_id LIMIT 200",
                [*anchors, *anchors],
            ):
                matched = next(
                    anchor
                    for anchor in anchors
                    if anchor == str(row["name"]).casefold() or anchor == str(row["qualified_name"]).casefold()
                )
                add(row["entity_id"], 500.0, "anchor", f"保留显式标识符 `{matched}`")
        if terms:
            placeholders = _sql_placeholders(terms)
            for row in connection.execute(
                f"SELECT term,entity_id,weight FROM terms WHERE term IN ({placeholders}) ORDER BY term,entity_id",
                terms,
            ):
                add(row["entity_id"], float(row["weight"]), "term", f"确定性词项 `{row['term']}`")
        fts = _fts_query(question)
        if fts:
            for row in connection.execute(
                "SELECT entity_id,bm25(entity_fts,0.0,10.0,9.0,4.0,4.0,3.0,3.0,5.0) AS rank FROM entity_fts WHERE entity_fts MATCH ? ORDER BY rank LIMIT ?",
                (fts, 80 if profile == "fast" else 240),
            ):
                add(row["entity_id"], 120.0 / (1.0 + abs(float(row["rank"]))), "entity-fts", "机器实体全文命中")
            for row in connection.execute(
                "SELECT section_fts.section_id,section_fts.document_id,d.source_entity_id,"
                "bm25(section_fts,0.0,0.0,6.0,2.0,1.0) AS rank "
                "FROM section_fts JOIN documents d ON d.document_id=section_fts.document_id "
                "WHERE section_fts MATCH ? ORDER BY rank LIMIT ?",
                (fts, 100 if profile == "fast" else 320),
            ):
                section_scores[row["section_id"]] = 90.0 / (1.0 + abs(float(row["rank"])))
                if row["source_entity_id"]:
                    add(row["source_entity_id"], section_scores[row["section_id"]], "section-fts", "中文章节全文命中")
            if profile == "precise":
                for row in connection.execute(
                    "SELECT e.entity_id,source_fts.source_path,bm25(source_fts) AS rank "
                    "FROM source_fts JOIN entities e ON e.source_path=source_fts.source_path "
                    "WHERE source_fts MATCH ? ORDER BY rank LIMIT 640",
                    (fts,),
                ):
                    add(row["entity_id"], 24.0 / (1.0 + abs(float(row["rank"]))), "source-fts", "固定源码全文命中")
        static_key = _static_retrieval_key(path, output)
        static_context = _RETRIEVAL_STATIC_CACHE.get(static_key)
        static_cache_hit = static_context is not None
        if static_context is not None:
            entity_columns = static_context["entity_columns"]
        else:
            entity_columns = {str(row[1]) for row in connection.execute("PRAGMA table_info(entities)")}
            static_context = _static_retrieval_context(connection, output, entity_columns, static_key)

        def entity_column(name: str) -> str:
            return name if name in entity_columns else f"'' AS {name}"

        metadata_rows = (
            static_context["metadata_rows"]
            if static_context is not None
            else connection.execute(
                "SELECT "
                + ",".join(
                    entity_column(name)
                    for name in (
                        "entity_id",
                        "kind",
                        "name",
                        "qualified_name",
                        "source_path",
                        "meaning_zh",
                        "role_zh",
                        "change_when_zh",
                        "description_zh",
                    )
                )
                + " FROM entities"
            ).fetchall()
        )
        metadata_by_id = {row["entity_id"]: row for row in metadata_rows}
        high_signal_terms = [
            term.casefold()
            for term in terms
            if len(term) >= 3 or (len(term) >= 2 and re.search(r"[a-z0-9_]", term, flags=re.IGNORECASE))
        ]
        for row in metadata_rows:
            name = str(row["name"]).casefold()
            qualified = str(row["qualified_name"]).casefold()
            source_path = str(row["source_path"]).casefold()
            narrative = " ".join(
                str(row[field] or "").casefold()
                for field in ("meaning_zh", "role_zh", "change_when_zh", "description_zh")
            )
            contribution = 0.0
            for term in high_signal_terms:
                if term == name or term == qualified:
                    contribution += 52.0
                elif term in name or term in qualified:
                    contribution += 30.0
                elif term in source_path:
                    contribution += 22.0
                elif term in narrative:
                    contribution += 12.0 if len(term) >= 4 else 5.0
            if contribution:
                if row["kind"] == "file":
                    contribution += 20.0
                add(row["entity_id"], contribution, "metadata", "文件、标识符和中文职责确定性匹配")
        test_intent = bool(re.search(r"(?:测试|验收|test|fixture|spec)", question, flags=re.IGNORECASE))
        if not test_intent:
            for entity_id in sorted(scores):
                row = metadata_by_id.get(entity_id)
                if row is None:
                    continue
                is_test = str(row["source_path"]).casefold().startswith("tests/") or str(row["name"]).casefold().startswith("test")
                if not is_test or breakdown[entity_id].get("exact") or breakdown[entity_id].get("anchor"):
                    continue
                original = scores[entity_id]
                discounted = original * IMPLEMENTATION_TEST_DISCOUNT
                add(entity_id, discounted - original, "test-discount", "实现定位查询对测试实体应用固定折扣")
        if not scores and not automation_rows:
            return {
                "schema_version": MACHINE_SCHEMA_VERSION,
                "status": "needs-source-read",
                "question": question,
                "profile": profile,
                "terms": terms,
                "anchors": anchors,
                "reason": "机器知识库没有来源绑定的候选，请按 scope 或源码路径继续读取。",
            }
        if not scores and automation_rows:
            pack_path, record_path = _next_pack_path(output)
            pack = (
                f"# Agent 机器知识阅读包\n\n问题：{question}\n\n检索档位：{profile}\n\n"
                "本阅读包只命中自动化会话记录；这些记录仍需按其状态完成 Agent 来源审阅。\n\n"
            )
            related = []
            for row in automation_rows:
                paths = "、".join(f"`{path}`" for path in row.get("changed_paths", [])) or "无项目文件变化"
                block = (
                    f"## {row['title']}\n\n"
                    f"状态：{row['status']}\n\n"
                    f"类型：{row['kind']}\n\n"
                    f"修改范围：{paths}\n\n"
                    f"{row['content'].strip()}\n\n"
                )
                if estimated_tokens(pack + block) > budget:
                    continue
                pack += block
                related.append(
                    {
                        "document_id": f"automation:{row['review_id']}",
                        "title": row["title"],
                        "kind": row["kind"],
                        "human_file": row.get("human_file"),
                        "status": row["status"],
                    }
                )
            if not related:
                raise CkbError("retrieve budget is too small for the matching automation record")
            pack_path.write_text(pack.rstrip() + "\n", encoding="utf-8", newline="\n")
            result = {
                "schema_version": MACHINE_SCHEMA_VERSION,
                "status": "passed",
                "question": question,
                "profile": profile,
                "budget": budget,
                "estimated_tokens": estimated_tokens(pack),
                "terms": terms,
                "anchors": anchors,
                "seed_entity_ids": [],
                "selected_entities": [],
                "related_documents": related,
                "pack": str(pack_path.resolve()),
                "record": str(record_path.resolve()),
                "retrieval": "sqlite-automation-fts5-trigram",
                "deterministic": True,
                "source_grounded": False,
                "pending_agent_review": any(item["status"] == "pending-agent-review" for item in related),
                "grep_fallback_required": False,
            }
            json_write(record_path, result)
            return result
        lexical_order = sorted(scores, key=lambda entity_id: (-scores[entity_id], entity_id))
        seeds = lexical_order[:5]
        seed_scores = {entity_id: scores[entity_id] for entity_id in seeds}
        if static_context is not None:
            adjacency, degree = static_context["adjacency"], static_context["degree"]
        else:
            adjacency, degree = _adjacency(connection)
        graph_scores = (
            _fast_graph_scores(seeds, seed_scores, adjacency, degree)
            if profile == "fast"
            else _deterministic_ppr(seeds, seed_scores, adjacency, degree)
        )
        maximum_seed = max(seed_scores.values()) or 1.0
        for entity_id, value in sorted(graph_scores.items()):
            contribution = (value if profile == "fast" else value * maximum_seed * 0.55)
            if contribution <= 0:
                continue
            add(entity_id, contribution, "graph", "查询相关种子的确定性图扩展")
        ordered = sorted(scores, key=lambda entity_id: (-scores[entity_id], entity_id))
        overscan_limit = FAST_RETRIEVAL_OVERSCAN if profile == "fast" else PRECISE_RETRIEVAL_OVERSCAN
        overscan_ids = ordered[:overscan_limit]
        if static_context is not None:
            entity_rows = {
                entity_id: static_context["entity_rows"][entity_id]
                for entity_id in overscan_ids
                if entity_id in static_context["entity_rows"]
            }
            sections_by_entity = {
                entity_id: static_context["sections"].get(entity_id, [])
                for entity_id in overscan_ids
            }
        else:
            entity_rows, sections_by_entity = _bulk_entity_context(connection, overscan_ids)
        budgeted_entity_limit = max(1, min(entity_limit, max(1, (budget - 80) // 180)))
        selected_ids = _diverse_candidates(overscan_ids, entity_rows, budgeted_entity_limit)
        pack_path, record_path = _next_pack_path(output)
        pack = f"# Agent 机器知识阅读包\n\n问题：{question}\n\n检索档位：{profile}\n\n所有说明使用简体中文；代码标识符保持源码形式。\n\n"
        selected: list[dict[str, Any]] = []
        linker = static_context["linker"] if static_context is not None else SourceLinkRenderer(_openers(output), trusted_relative_paths=True)
        for index, entity_id in enumerate(selected_ids):
            entity = entity_rows[entity_id]
            remaining_bytes = max(0, budget * 3 - len(pack.encode("utf-8")) - 16)
            remaining_slots = max(1, len(selected_ids) - index)
            allocation = max(180, remaining_bytes // remaining_slots)
            source_link = linker.markdown_link(
                entity["source_path"],
                int(entity["start_line"]),
                int(entity["end_line"]),
            )
            block, included_sections = _compact_entity_block(
                entity,
                sections_by_entity.get(entity_id, []),
                section_scores,
                reasons[entity_id],
                source_link,
                allocation,
                profile,
            )
            available = max(0, budget * 3 - len(pack.encode("utf-8")) - 4)
            if len(block.encode("utf-8")) > available:
                block = _utf8_prefix(block, available).rstrip() + "\n"
            pack += block
            selected.append(
                {
                    "entity_id": entity_id,
                    "name": entity["name"],
                    "qualified_name": entity["qualified_name"],
                    "kind": entity["kind"],
                    "source_path": entity["source_path"],
                    "start_line": entity["start_line"],
                    "end_line": entity["end_line"],
                    "human_page_title": entity["human_title"],
                    "human_page_file": entity["page_file"],
                    "display_mode": entity["display_mode"],
                    "score": round(scores[entity_id], 8),
                    "score_breakdown": {key: round(value, 8) for key, value in sorted(breakdown[entity_id].items())},
                    "reasons": list(dict.fromkeys(reasons[entity_id])),
                    "sections": included_sections,
                }
            )
        note_rows = []
        if fts:
            seen_documents: set[str] = set()
            for row in connection.execute(
                "SELECT d.document_id,d.title,d.kind,d.human_file,bm25(section_fts,0.0,0.0,6.0,2.0,1.0) AS rank FROM section_fts JOIN documents d ON d.document_id=section_fts.document_id WHERE section_fts MATCH ? AND d.kind<>'entity' ORDER BY rank LIMIT 40",
                (fts,),
            ):
                if row["document_id"] in seen_documents:
                    continue
                seen_documents.add(row["document_id"])
                note_rows.append({"document_id": row["document_id"], "title": row["title"], "kind": row["kind"], "human_file": row["human_file"]})
                if len(note_rows) >= 8:
                    break
        seen_document_ids = {row["document_id"] for row in note_rows}
        for row in automation_rows:
            document_id = f"automation:{row['review_id']}"
            if document_id in seen_document_ids:
                continue
            note_rows.append(
                {
                    "document_id": document_id,
                    "title": row["title"],
                    "kind": row["kind"],
                    "human_file": row.get("human_file"),
                    "status": row["status"],
                }
            )
            if len(note_rows) >= 8:
                break
    finally:
        connection.close()
    if not selected:
        raise CkbError("retrieve budget is too small for the highest-ranked machine entity")
    pack_path.write_text(pack.rstrip() + "\n", encoding="utf-8", newline="\n")
    result = {
        "schema_version": MACHINE_SCHEMA_VERSION,
        "status": "passed",
        "question": question,
        "profile": profile,
        "budget": budget,
        "estimated_tokens": estimated_tokens(pack),
        "terms": terms,
        "anchors": anchors,
        "seed_entity_ids": seeds,
        "selected_entities": selected,
        "related_documents": note_rows,
        "retrieval_stats": {
            "scored_entities": len(scores),
            "overscan_limit": overscan_limit,
            "materialized_candidates": len(overscan_ids),
            "selected_entities": len(selected),
            "budgeted_entity_limit": budgeted_entity_limit,
            "selected_source_paths": len({item["source_path"] for item in selected}),
            "batched_entity_queries": 2,
            "source_link_cache_entries": linker.cache_size,
            "static_cache_hit": static_cache_hit,
        },
        "pack": str(pack_path.resolve()),
        "record": str(record_path.resolve()),
        "retrieval": "sqlite-exact-fts5-sections-deterministic-weighted-graph",
        "deterministic": True,
        "source_grounded": True,
        "grep_fallback_required": False,
    }
    json_write(record_path, result)
    return result


def coverage(output: Path) -> dict[str, Any]:
    audit = audit_machine_knowledge(output)
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        reviewed = connection.execute("SELECT count(*) FROM reviews WHERE status='agent-reviewed'").fetchone()[0]
        chinese = connection.execute(
            "SELECT count(*) FROM entities WHERE (classification='appendix' AND description_zh GLOB '*[一-龥]*') OR (classification<>'appendix' AND meaning_zh GLOB '*[一-龥]*' AND role_zh GLOB '*[一-龥]*' AND change_when_zh GLOB '*[一-龥]*')"
        ).fetchone()[0]
        total = connection.execute("SELECT count(*) FROM entities").fetchone()[0]
    finally:
        connection.close()
    return {
        "schema_version": MACHINE_SCHEMA_VERSION,
        "status": "passed" if audit.get("status") == "passed" and reviewed == total and chinese == total else "failed",
        "entities": total,
        "agent_reviewed": reviewed,
        "chinese_descriptions": chinese,
        "coverage_ratio": 1.0 if total == 0 else chinese / total,
        "audit": audit,
    }


def entity_lookup(output: Path, selector: str) -> dict[str, Any]:
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        rows = connection.execute(
            "SELECT e.*,r.start_line,r.end_line,h.title AS human_title,h.page_file,h.display_mode FROM entities e JOIN source_ranges r USING(entity_id) LEFT JOIN human_projection h USING(entity_id) WHERE e.entity_id=? OR e.name=? COLLATE NOCASE OR e.qualified_name=? COLLATE NOCASE ORDER BY e.qualified_name LIMIT 20",
            (selector, selector, selector),
        ).fetchall()
    finally:
        connection.close()
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed" if rows else "not-found", "selector": selector, "candidates": [dict(row) for row in rows]}


def neighbor_lookup(output: Path, selector: str, depth: int = 1, relation: str | None = None, limit: int = 50) -> dict[str, Any]:
    if depth < 1 or depth > 6:
        raise CkbError("neighbor depth must be in [1, 6]")
    found = entity_lookup(output, selector)
    if len(found["candidates"]) != 1:
        return {**found, "reason": "selector must match exactly one entity"}
    root_id = found["candidates"][0]["entity_id"]
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        visited = {root_id}
        frontier = {root_id}
        rows: list[dict[str, Any]] = []
        for current_depth in range(1, depth + 1):
            next_frontier: set[str] = set()
            for entity_id in sorted(frontier):
                query = "SELECT * FROM relations WHERE (source_entity_id=? OR target_entity_id=?)"
                params: list[Any] = [entity_id, entity_id]
                if relation:
                    query += " AND relation=?"
                    params.append(relation)
                query += " ORDER BY relation_id"
                for row in connection.execute(query, params):
                    target = row["target_entity_id"] if row["source_entity_id"] == entity_id else row["source_entity_id"]
                    entity = connection.execute("SELECT name,qualified_name,source_path FROM entities WHERE entity_id=?", (target,)).fetchone()
                    rows.append({"depth": current_depth, "from": entity_id, "entity_id": target, "relation": row["relation"], "direction": "outgoing" if row["source_entity_id"] == entity_id else "incoming", **dict(entity)})
                    if target not in visited:
                        visited.add(target)
                        next_frontier.add(target)
                    if len(rows) >= limit:
                        break
                if len(rows) >= limit:
                    break
            frontier = next_frontier
            if not frontier or len(rows) >= limit:
                break
    finally:
        connection.close()
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "selector": selector, "root_entity_id": root_id, "depth": depth, "relation": relation, "neighbors": rows}


def source_lookup(output: Path, selector: str, context_lines: int = 3) -> dict[str, Any]:
    found = entity_lookup(output, selector)
    if len(found["candidates"]) != 1:
        return {**found, "reason": "selector must match exactly one entity"}
    entity = found["candidates"][0]
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        row = connection.execute("SELECT source_text FROM files WHERE path=?", (entity["source_path"],)).fetchone()
    finally:
        connection.close()
    if row is None:
        return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "not-found", "selector": selector, "reason": "source file is absent from the fixed snapshot"}
    lines = row[0].splitlines()
    start = max(1, int(entity["start_line"]) - context_lines)
    end = min(len(lines), int(entity["end_line"]) + context_lines)
    excerpt = "\n".join(f"{index:>6}  {lines[index - 1]}" for index in range(start, end + 1))
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "selector": selector, "entity_id": entity["entity_id"], "source_path": entity["source_path"], "start_line": start, "end_line": end, "excerpt": excerpt}


def change_documents(output: Path, kind: str | None = None, limit: int = 20) -> dict[str, Any]:
    path = output / MACHINE_PATH
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        query = "SELECT document_id,kind,title,human_file,token_estimate FROM documents WHERE kind<>'entity'"
        params: list[Any] = []
        if kind:
            query += " AND kind=?"
            params.append(kind)
        query += " ORDER BY document_id DESC LIMIT ?"
        params.append(limit)
        rows = [dict(row) for row in connection.execute(query, params)]
    finally:
        connection.close()
    from .automation import automation_documents

    automated = automation_documents(output, kind, limit)
    combined = rows + automated
    combined.sort(key=lambda item: str(item.get("document_id", "")), reverse=True)
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "kind": kind, "documents": combined[:limit]}


def sync_workspace_changes(output: Path) -> dict[str, Any]:
    path = output / MACHINE_PATH
    overlay = output / "workspace-meta/working-overlay.json"
    if not path.is_file() or not overlay.is_file():
        return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "skipped", "reason": "machine database or working overlay is absent"}
    value = json_load(overlay)
    connection = sqlite3.connect(path)
    try:
        connection.execute("DELETE FROM workspace_changes")
        detail = json.dumps(value, ensure_ascii=False, sort_keys=True)
        for changed in value.get("changed_paths", []):
            connection.execute("INSERT INTO workspace_changes VALUES(?,?,?)", (changed, "changed", detail))
        for untracked in value.get("untracked_paths", []):
            connection.execute("INSERT INTO workspace_changes VALUES(?,?,?)", (untracked, "untracked", detail))
        connection.commit()
    finally:
        connection.close()
    return {"schema_version": MACHINE_SCHEMA_VERSION, "status": "passed", "changed": len(value.get("changed_paths", [])), "untracked": len(value.get("untracked_paths", []))}

"""Minimal, plugin-free Obsidian vault projection and ownership tracking."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .common import CkbError, json_load, json_write, safe_rmtree


NOTE_DIRECTORIES = ("analysis", "changes", "pitfalls", "experiments", "sessions")
GENERATED_TOP_LEVEL = (
    "INDEX.md",
    "WIKI.md",
    "normalized.edn",
    "projection.json",
    "context-budget.json",
    "readability-audit.json",
)


def prepare_vault(root: Path, output: Path) -> None:
    """Remove only generator-owned files and preserve Agent/user notes."""
    root.mkdir(parents=True, exist_ok=True)
    ownership = root / ".ckb-generated-files.json"
    if ownership.is_file():
        record = json_load(ownership)
        for relative in record.get("files", []):
            path = root / str(relative)
            if path.is_file():
                path.unlink()
            elif path.is_dir():
                safe_rmtree(path, root)
    else:
        for name in GENERATED_TOP_LEVEL:
            (root / name).unlink(missing_ok=True)
        for name in ("pages", "logseq"):
            path = root / name
            if path.exists():
                safe_rmtree(path, root)
    for name in NOTE_DIRECTORIES:
        (root / name).mkdir(parents=True, exist_ok=True)


def install_obsidian(root: Path) -> dict[str, Any]:
    config = root / ".obsidian"
    snippets = config / "snippets"
    snippets.mkdir(parents=True, exist_ok=True)
    app = {
        "newLinkFormat": "shortest",
        "useMarkdownLinks": False,
        "alwaysUpdateLinks": True,
        "attachmentFolderPath": "attachments",
        "showUnsupportedFiles": True,
        "defaultViewMode": "preview",
    }
    plugins = [
        "file-explorer",
        "global-search",
        "switcher",
        "graph",
        "backlink",
        "outgoing-link",
        "tag-pane",
        "page-preview",
        "outline",
        "command-palette",
    ]
    appearance = {"enabledCssSnippets": ["ckb"]}
    css = """/* Code Knowledge Builder: restrained source links and appendices. */
/* Generated Markdown already has one portable H1.  Obsidian's filename-based
   inline title would repeat that heading, so the vault shows only the H1. */
body .inline-title { display: none; }
.external-link[href^="vscode://"],
.external-link[href^="vscode-insiders://"] { color: var(--text-accent); }
.markdown-rendered table { width: 100%; }
.markdown-rendered details { border-left: 2px solid var(--background-modifier-border); padding-left: 0.8rem; }
"""
    json_write(config / "app.json", app)
    json_write(config / "core-plugins.json", plugins)
    json_write(config / "appearance.json", appearance)
    (snippets / "ckb.css").write_text(css, encoding="utf-8", newline="\n")
    return {
        "status": "ready",
        "vault_root": str(root.resolve()),
        "config_root": str(config.resolve()),
        "core_plugins": plugins,
        "home": "INDEX.md",
        "note_directories": list(NOTE_DIRECTORIES),
    }


def write_generated_ownership(root: Path, generated: list[Path]) -> dict[str, Any]:
    files = sorted(path.relative_to(root).as_posix() for path in generated if path.is_file())
    record = {"schema_version": 1, "status": "ready", "files": files}
    json_write(root / ".ckb-generated-files.json", record)
    return record


def audit_obsidian(root: Path) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    required = (
        ".obsidian/app.json",
        ".obsidian/core-plugins.json",
        ".obsidian/appearance.json",
        ".obsidian/snippets/ckb.css",
        ".ckb-generated-files.json",
        "INDEX.md",
        "WIKI.md",
    )
    for relative in required:
        if not (root / relative).is_file():
            errors.append({"reason": "obsidian-vault-file-missing", "path": relative})
    for name in NOTE_DIRECTORIES:
        if not (root / name).is_dir():
            errors.append({"reason": "obsidian-note-directory-missing", "path": name})
    ownership = root / ".ckb-generated-files.json"
    if ownership.is_file() and ".obsidian/workspace.json" in json_load(ownership).get("files", []):
        errors.append({"reason": "machine-specific-obsidian-workspace-owned-by-generator"})
    try:
        plugins = json_load(root / ".obsidian/core-plugins.json")
        for plugin in ("backlink", "outgoing-link", "tag-pane", "graph", "global-search"):
            if plugin not in plugins:
                errors.append({"reason": "obsidian-core-plugin-missing", "plugin": plugin})
    except (OSError, json.JSONDecodeError, CkbError) as exc:
        errors.append({"reason": "obsidian-config-invalid", "detail": str(exc)})
    css_path = root / ".obsidian/snippets/ckb.css"
    if css_path.is_file():
        css = css_path.read_text(encoding="utf-8")
        if "body .inline-title { display: none; }" not in css:
            errors.append({"reason": "obsidian-inline-title-not-hidden"})
    return errors

from __future__ import annotations

import copy
import hashlib
import json
from pathlib import Path
from typing import Any

from .common import CkbError


PAGE_CONFIG_SCHEMA_VERSION = 1

# Keep one embedded default so a lite installation can validate and start even
# when the caller does not supply a configuration file.  The packaged
# references/page-config.default.json is byte-compared with this value by tests.
DEFAULT_PAGE_CONFIG: dict[str, Any] = {
    "schema_version": PAGE_CONFIG_SCHEMA_VERSION,
    "page_limits": {
        "ordinary_file": 1,
        "core_file": 4,
        "adjacent_file": 1,
        "core_per_entry": 4,
        "adjacent_per_entry": 3,
    },
    "content": {
        "code_page_sections": [
            "overview",
            "change_when",
            "source_location",
            "partial_fragments",
            "related_code",
            "backlinks",
            "tests",
            "hidden_relation_hint",
            "appendix",
        ],
        "aggregate_page_sections": [
            "overview",
            "related_code",
            "backlinks",
            "tests",
            "hidden_relation_hint",
        ],
        "boundary_page_sections": [
            "overview",
            "boundary_details",
            "related_code",
            "backlinks",
            "hidden_relation_hint",
        ],
        "overview_fields": ["meaning", "role"],
        "appendix_mode": "collapsed",
        "headings": {
            "change_when": "什么时候需要修改",
            "source_location": "在代码中的位置",
            "boundary_details": "本次未继续展开的代码",
            "related_code": "相关代码",
            "backlinks": "谁会来到这里",
            "tests": "相关测试",
            "appendix": "内部细节",
        },
    },
    "relation_limits": {
        "direct": 20,
        "aggregate": 10,
        "test": 8,
        "boundary": 8,
    },
    "context": {
        "module_max_tokens": 80_000,
        "task_max_tokens": 20_000,
        "total_max_tokens": 100_000,
        "reserved_agent_tokens": 20_000,
        "bytes_per_token": 3,
    },
    "review_packs": {
        "page": {"max_files": 12, "max_items": 20, "max_tokens": 20_000},
        "appendix": {"max_files": 8, "max_items": 120, "max_tokens": 15_000},
    },
}

_CODE_SECTIONS = {
    "overview",
    "change_when",
    "source_location",
    "partial_fragments",
    "related_code",
    "backlinks",
    "tests",
    "hidden_relation_hint",
    "appendix",
}
_AGGREGATE_SECTIONS = {"overview", "related_code", "backlinks", "tests", "hidden_relation_hint"}
_BOUNDARY_SECTIONS = {"overview", "boundary_details", "related_code", "backlinks", "hidden_relation_hint"}
_REQUIRED_SECTIONS = {
    "code_page_sections": {"overview", "source_location", "appendix"},
    "aggregate_page_sections": {"overview"},
    "boundary_page_sections": {"overview", "boundary_details"},
}
_SECTION_SETS = {
    "code_page_sections": _CODE_SECTIONS,
    "aggregate_page_sections": _AGGREGATE_SECTIONS,
    "boundary_page_sections": _BOUNDARY_SECTIONS,
}


def _merge_known(default: Any, supplied: Any, path: str) -> Any:
    if isinstance(default, dict):
        if not isinstance(supplied, dict):
            raise CkbError(f"page config {path or '<root>'} must be an object")
        unknown = sorted(set(supplied) - set(default))
        if unknown:
            raise CkbError(f"page config has unknown keys at {path or '<root>'}: {unknown}")
        return {
            key: _merge_known(value, supplied[key], f"{path}.{key}".strip(".")) if key in supplied else copy.deepcopy(value)
            for key, value in default.items()
        }
    return copy.deepcopy(supplied)


def _integer(value: Any, path: str, minimum: int, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
        raise CkbError(f"page config {path} must be an integer in [{minimum}, {maximum}]")
    return value


def _section_list(config: dict[str, Any], name: str) -> None:
    value = config["content"][name]
    if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
        raise CkbError(f"page config content.{name} must be a string array")
    if len(value) != len(set(value)):
        raise CkbError(f"page config content.{name} contains duplicate sections")
    unknown = sorted(set(value) - _SECTION_SETS[name])
    if unknown:
        raise CkbError(f"page config content.{name} has unknown sections: {unknown}")
    missing = sorted(_REQUIRED_SECTIONS[name] - set(value))
    if missing:
        raise CkbError(
            f"page config content.{name} omits audited required sections: {missing}"
        )


def normalize_page_config(value: dict[str, Any]) -> dict[str, Any]:
    """Merge a partial user JSON with defaults and enforce the audit contract."""
    if not isinstance(value, dict):
        raise CkbError("page config root must be a JSON object")
    if value.get("schema_version") != PAGE_CONFIG_SCHEMA_VERSION:
        raise CkbError(
            f"page config schema_version must be {PAGE_CONFIG_SCHEMA_VERSION}"
        )
    config = _merge_known(DEFAULT_PAGE_CONFIG, value, "")

    limits = config["page_limits"]
    for key in ("ordinary_file", "core_file", "adjacent_file"):
        limits[key] = _integer(limits[key], f"page_limits.{key}", 0, 32)
    for key in ("core_per_entry", "adjacent_per_entry"):
        limits[key] = _integer(limits[key], f"page_limits.{key}", 0, 64)

    for name in _SECTION_SETS:
        _section_list(config, name)
    fields = config["content"]["overview_fields"]
    if (
        not isinstance(fields, list)
        or not fields
        or len(fields) != len(set(fields))
        or any(value not in {"meaning", "role"} for value in fields)
    ):
        raise CkbError(
            "page config content.overview_fields must contain one or both of: meaning, role"
        )
    if config["content"]["appendix_mode"] not in {"collapsed", "expanded"}:
        raise CkbError("page config content.appendix_mode must be collapsed or expanded")
    headings = config["content"]["headings"]
    for key, heading in headings.items():
        if not isinstance(heading, str) or not heading.strip() or len(heading) > 64 or "\n" in heading or "\r" in heading:
            raise CkbError(f"page config content.headings.{key} must be one non-empty line of at most 64 characters")
        headings[key] = heading.strip()

    relation_limits = config["relation_limits"]
    for key in ("direct", "aggregate", "test", "boundary"):
        relation_limits[key] = _integer(relation_limits[key], f"relation_limits.{key}", 0, 200)

    context = config["context"]
    context["module_max_tokens"] = _integer(context["module_max_tokens"], "context.module_max_tokens", 1_000, 1_000_000)
    context["task_max_tokens"] = _integer(context["task_max_tokens"], "context.task_max_tokens", 500, 1_000_000)
    context["total_max_tokens"] = _integer(context["total_max_tokens"], "context.total_max_tokens", 1_000, 2_000_000)
    context["reserved_agent_tokens"] = _integer(context["reserved_agent_tokens"], "context.reserved_agent_tokens", 0, 1_000_000)
    context["bytes_per_token"] = _integer(context["bytes_per_token"], "context.bytes_per_token", 1, 16)
    if context["task_max_tokens"] > context["module_max_tokens"]:
        raise CkbError("page config context.task_max_tokens must not exceed module_max_tokens")
    if context["module_max_tokens"] + context["reserved_agent_tokens"] > context["total_max_tokens"]:
        raise CkbError(
            "page config context.module_max_tokens plus reserved_agent_tokens must not exceed total_max_tokens"
        )

    review = config["review_packs"]
    for kind in ("page", "appendix"):
        review[kind]["max_files"] = _integer(review[kind]["max_files"], f"review_packs.{kind}.max_files", 1, 200)
        review[kind]["max_items"] = _integer(review[kind]["max_items"], f"review_packs.{kind}.max_items", 1, 5_000)
        review[kind]["max_tokens"] = _integer(review[kind]["max_tokens"], f"review_packs.{kind}.max_tokens", 500, 1_000_000)
        if review[kind]["max_tokens"] > context["total_max_tokens"] - context["reserved_agent_tokens"]:
            raise CkbError(
                f"page config review_packs.{kind}.max_tokens exceeds the non-Agent context budget"
            )
    return config


def load_page_config(path: Path | None) -> tuple[dict[str, Any], str]:
    if path is None:
        return copy.deepcopy(DEFAULT_PAGE_CONFIG), "builtin-default"
    resolved = path.resolve()
    if not resolved.is_file():
        raise CkbError(f"page config does not exist: {resolved}")
    try:
        supplied = json.loads(resolved.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError) as exc:
        raise CkbError(f"page config is not valid JSON: {resolved}: {exc}") from exc
    return normalize_page_config(supplied), str(resolved)


def page_config_bytes(config: dict[str, Any]) -> bytes:
    normalized = normalize_page_config(config)
    return (json.dumps(normalized, ensure_ascii=False, indent=2) + "\n").encode("utf-8")


def page_config_sha256(config: dict[str, Any]) -> str:
    return hashlib.sha256(page_config_bytes(config)).hexdigest()


def write_page_config(path: Path, config: dict[str, Any], *, overwrite: bool = False) -> dict[str, Any]:
    resolved = path.resolve()
    if resolved.exists() and not overwrite:
        raise CkbError(f"page config output already exists: {resolved}; use --force to replace it")
    resolved.parent.mkdir(parents=True, exist_ok=True)
    content = page_config_bytes(config)
    resolved.write_bytes(content)
    return {
        "schema_version": PAGE_CONFIG_SCHEMA_VERSION,
        "path": str(resolved),
        "sha256": hashlib.sha256(content).hexdigest(),
        "status": "passed",
    }

from __future__ import annotations

import re
from pathlib import Path
from typing import Any, Iterator

from .common import DependencyError, stable_id


DECLARATION_TYPES = {
    "python": {
        "function_definition": "function",
        "class_definition": "class",
    },
    "javascript": {
        "function_declaration": "function",
        "generator_function_declaration": "function",
        "class_declaration": "class",
        "method_definition": "method",
        "variable_declarator": "variable",
    },
    "c": {
        "function_definition": "function",
        "declaration": "declaration",
        "struct_specifier": "class",
        "enum_specifier": "enum",
        "type_definition": "type",
    },
    "cpp": {
        "function_definition": "function",
        "function_declarator": "function",
        "class_specifier": "class",
        "struct_specifier": "class",
        "enum_specifier": "enum",
        "namespace_definition": "namespace",
        "type_definition": "type",
        "template_declaration": "template",
    },
    "csharp": {
        "namespace_declaration": "namespace",
        "file_scoped_namespace_declaration": "namespace",
        "class_declaration": "class",
        "struct_declaration": "struct",
        "record_declaration": "record",
        "interface_declaration": "interface",
        "delegate_declaration": "delegate",
        "enum_declaration": "enum",
        "enum_member_declaration": "enum_member",
        "method_declaration": "method",
        "local_function_statement": "local_function",
        "constructor_declaration": "constructor",
        "operator_declaration": "operator",
        "conversion_operator_declaration": "conversion_operator",
        "property_declaration": "property",
        "indexer_declaration": "indexer",
        "event_declaration": "event",
        "event_field_declaration": "event",
        "accessor_declaration": "accessor",
        "field_declaration": "field",
    },
}

NAME_FIELDS = ("name", "declarator", "type")


def _language(language: str):
    try:
        from tree_sitter import Language
        modules = {
            "python": "tree_sitter_python",
            "javascript": "tree_sitter_javascript",
            "c": "tree_sitter_c",
            "cpp": "tree_sitter_cpp",
            "csharp": "tree_sitter_c_sharp",
        }
        module = __import__(modules[language])
        return Language(module.language())
    except Exception as exc:
        raise DependencyError(f"Tree-sitter runtime for {language} is unavailable: {exc}") from exc


def _walk(node) -> Iterator[Any]:
    stack = [node]
    while stack:
        current = stack.pop()
        yield current
        stack.extend(reversed(current.children))


def _node_text(node, source: bytes) -> str:
    return source[node.start_byte : node.end_byte].decode("utf-8", errors="replace")


def _byte_position(source: bytes, byte_offset: int) -> tuple[int, int]:
    """Compute 1-based line and UTF-8 byte column without Node Point access."""
    previous_newline = source.rfind(b"\n", 0, byte_offset)
    return source.count(b"\n", 0, byte_offset) + 1, byte_offset - (previous_newline + 1)


def _find_name(node, source: bytes, retained_nodes: list[Any]) -> tuple[str, int, int] | None:
    for field in NAME_FIELDS:
        child = node.child_by_field_name(field)
        if child is not None:
            candidates = [child, *_walk(child)]
            retained_nodes.extend(candidates)
            for value in candidates:
                if value.type in {"identifier", "type_identifier", "field_identifier", "property_identifier", "namespace_identifier"}:
                    line, column = _byte_position(source, value.start_byte)
                    return _node_text(value, source), line, column
    fallback_nodes = list(_walk(node))
    retained_nodes.extend(fallback_nodes)
    for child in fallback_nodes:
        if child.type in {"identifier", "type_identifier", "field_identifier", "property_identifier", "namespace_identifier"}:
            line, column = _byte_position(source, child.start_byte)
            return _node_text(child, source), line, column
    return None


def _public_evidence(language: str, source_text: str, node_text: str, name: str) -> bool:
    if language == "python":
        return not name.startswith("_")
    if language == "javascript":
        return bool(re.search(r"\bexport\b", source_text[max(0, source_text.find(node_text) - 80) : source_text.find(node_text) + 20]))
    return bool(re.search(r"\b(public|protected|internal|extern)\b", node_text)) or language in {"c", "cpp"}


PAGE_ELIGIBLE_KINDS = {
    "class",
    "struct",
    "record",
    "interface",
    "delegate",
    "function",
    "method",
    "local_function",
    "constructor",
    "operator",
    "conversion_operator",
    "property",
    "indexer",
    "event",
    "accessor",
}


def _single_statement_shape(node, source: bytes, kind: str) -> str | None:
    """Return a small deterministic hard-exclusion reason for thin declarations."""
    if kind == "accessor":
        return "accessor"
    if kind not in {"function", "method", "local_function", "constructor", "operator", "conversion_operator", "property", "indexer", "event"}:
        return None
    body = node.child_by_field_name("body")
    if body is None:
        # Expression-bodied C# members and declarations without a block.
        text = _node_text(node, source)
        if "=>" in text:
            return "single-expression-body"
        return None
    named = [child for child in body.named_children if child.type not in {"comment"}]
    if len(named) != 1:
        return None
    statement = named[0]
    text = _node_text(statement, source)
    if statement.type in {"return_statement", "expression_statement"}:
        if not re.search(r"\b(if|for|foreach|while|switch|try|catch|await|yield|throw|lock)\b", text):
            return "single-return-or-call"
    if statement.type in {"assignment_expression", "local_declaration_statement"}:
        return "single-assignment"
    return None


def _csharp_fallback_name(node, source: bytes, kind: str) -> tuple[str, int, int] | None:
    text = _node_text(node, source)
    if kind == "indexer":
        line, column = _byte_position(source, node.start_byte)
        return "this", line, column
    if kind == "accessor":
        match = re.search(r"\b(get|set|init|add|remove)\b", text)
        if match:
            absolute = node.start_byte + len(text[: match.start()].encode("utf-8"))
            line, column = _byte_position(source, absolute)
            return match.group(1), line, column
    if kind in {"operator", "conversion_operator"}:
        match = re.search(r"\boperator\s+([^\s({]+)", text)
        label = f"operator {match.group(1)}" if match else kind.replace("_", " ")
        line, column = _byte_position(source, node.start_byte)
        return label, line, column
    return None


def parse_file(repository: dict[str, Any], file_entry: dict[str, Any], source: bytes) -> dict[str, Any]:
    try:
        from tree_sitter import Parser
    except Exception as exc:
        raise DependencyError(f"Tree-sitter Python binding is unavailable: {exc}") from exc
    # Keep the Language wrapper alive for the full tree/node lifetime.  The
    # native binding owns parser tables through this object; a temporary can be
    # collected during large traversals and invalidate later Node access.
    language = _language(file_entry["language"])
    parser = Parser(language)
    tree = parser.parse(source)
    root = tree.root_node
    source_text = source.decode("utf-8", errors="replace")
    file_entity = {
        "id": file_entry["id"],
        "kind": "file",
        "name": Path(file_entry["path"]).name,
        "qualified_name": file_entry["path"],
        "language": file_entry["language"],
        "path": file_entry["path"],
        "blob": file_entry["blob"],
        "commit": repository["commit"],
        "range": {
            "start_byte": 0,
            "end_byte": len(source),
            "start_line": 1,
            "end_line": max(1, source.count(b"\n") + 1),
        },
        "parent_id": None,
        "candidate_classification": "page",
        "classification_evidence": ["file-always-page"],
    }
    entities = [file_entity]
    entity_kind_by_id = {file_entity["id"]: "file"}
    ranges: list[tuple[int, int, str, str]] = []
    file_scoped_namespace: tuple[str, str, int] | None = None
    declarations = DECLARATION_TYPES[file_entry["language"]]
    seen: set[tuple[str, int, int]] = set()
    # Keep every wrapper alive until extraction finishes.  tree-sitter 0.26 on
    # Windows can release native node context too early when generator-produced
    # wrappers are destroyed during a long traversal.
    syntax_nodes = list(_walk(root))
    retained_nodes: list[Any] = list(syntax_nodes)
    for node in syntax_nodes:
        node_type = node.type
        kind = declarations.get(node_type)
        if not kind:
            continue
        start_byte = node.start_byte
        end_byte = node.end_byte
        start_line, _start_column = _byte_position(source, start_byte)
        end_line, _end_column = _byte_position(source, end_byte)
        named = _find_name(node, source, retained_nodes) or _csharp_fallback_name(node, source, kind)
        if file_entry["language"] == "csharp" and kind == "namespace":
            namespace_name = node.child_by_field_name("name")
            if namespace_name is not None:
                line, column = _byte_position(source, namespace_name.start_byte)
                named = (_node_text(namespace_name, source).strip(), line, column)
        if not named:
            continue
        name, name_line, name_column = named
        if not name or len(name) > 240:
            continue
        key = (name, start_byte, end_byte)
        if key in seen:
            continue
        seen.add(key)
        parent_name = None
        parent_id = file_entity["id"]
        for start, end, candidate_name, candidate_id in reversed(ranges):
            if start <= start_byte and end_byte <= end:
                parent_name = candidate_name
                parent_id = candidate_id
                break
        if parent_name is None and file_scoped_namespace and start_byte >= file_scoped_namespace[2]:
            parent_name, parent_id, _namespace_end = file_scoped_namespace
        qualified = f"{parent_name}.{name}" if parent_name else name
        if node_type == "function_declarator" and entity_kind_by_id.get(parent_id) == "function":
            continue
        node_text = source[start_byte:end_byte].decode("utf-8", errors="replace")
        line_count = end_line - start_line + 1
        hard_exclusion = (
            f"csharp-default-appendix:{kind}"
            if file_entry["language"] == "csharp" and kind in {"property", "indexer", "event", "accessor"}
            else _single_statement_shape(node, source, kind)
        )
        simple = kind not in PAGE_ELIGIBLE_KINDS or hard_exclusion is not None
        public = _public_evidence(file_entry["language"], source_text, node_text, name)
        effects = bool(re.search(r"\b(open|write|save|delete|remove|request|fetch|socket|subprocess|exec|spawn|commit|send|recv)\b", node_text, re.I))
        evidence = []
        if public:
            evidence.append("public-or-exported")
        if kind == "class":
            evidence.append("class-boundary")
        if effects:
            evidence.append("side-effect-orchestration")
        if simple:
            evidence.append("simple-attached-entity")
        candidate = "page" if kind in PAGE_ELIGIBLE_KINDS and not simple else "appendix"
        entity_id = stable_id("ent", repository["commit"], file_entry["blob"], file_entry["path"], start_byte, end_byte, kind, name)
        entity = {
            "id": entity_id,
            "kind": kind,
            "name": name,
            "qualified_name": qualified,
            "language": file_entry["language"],
            "path": file_entry["path"],
            "blob": file_entry["blob"],
            "commit": repository["commit"],
            "range": {
                "start_byte": start_byte,
                "end_byte": end_byte,
                "start_line": start_line,
                "end_line": end_line,
                "name_line": name_line,
                "name_column_utf8": name_column,
            },
            "parent_id": parent_id,
            "candidate_classification": candidate,
            "classification_evidence": evidence or ["attached-by-default"],
            "page_eligible": kind in PAGE_ELIGIBLE_KINDS and hard_exclusion is None,
            "hard_exclusion": hard_exclusion,
            "is_public_or_exported": public,
            "is_partial": file_entry["language"] == "csharp" and bool(re.search(r"\bpartial\b", node_text[: min(len(node_text), 240)])),
        }
        entities.append(entity)
        entity_kind_by_id[entity_id] = kind
        ranges.append((start_byte, end_byte, qualified, entity_id))
        if node_type == "file_scoped_namespace_declaration":
            file_scoped_namespace = (qualified, entity_id, end_byte)
    return {
        "file": file_entry,
        "parse": {
            "status": "failed" if root.has_error else "passed",
            "root_type": root.type,
            "has_error": bool(root.has_error),
        },
        "entities": entities,
    }


def merge_csharp_partials(repository: dict[str, Any], entities: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Merge partial C# type declarations into one logical entity with audited fragments."""
    type_kinds = {"class", "struct", "record", "interface"}
    groups: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for entity in entities:
        if entity.get("language") == "csharp" and entity.get("kind") in type_kinds and entity.get("is_partial"):
            groups.setdefault((entity["kind"], entity["qualified_name"]), []).append(entity)
    replacements: dict[str, str] = {}
    merged_by_old: dict[str, dict[str, Any]] = {}
    removed: set[str] = set()
    for (kind, qualified), values in sorted(groups.items()):
        if len(values) < 2:
            continue
        ordered = sorted(values, key=lambda item: (item["path"], item["range"]["start_byte"], item["id"]))
        primary = sorted(
            ordered,
            key=lambda item: (
                -sum(1 for child in entities if child.get("parent_id") == item["id"] and child.get("page_eligible")),
                item["path"],
                item["range"]["start_byte"],
                item["id"],
            ),
        )[0]
        logical_id = stable_id("ent", repository["commit"], "csharp-partial", kind, qualified)
        logical = dict(primary)
        logical["id"] = logical_id
        logical["partial"] = True
        logical["fragments"] = [
            {
                "fragment_id": value["id"],
                "path": value["path"],
                "blob": value["blob"],
                "range": value["range"],
            }
            for value in ordered
        ]
        logical["classification_evidence"] = sorted(set(logical.get("classification_evidence", []) + ["partial-logical-entity"]))
        for value in ordered:
            replacements[value["id"]] = logical_id
            merged_by_old[value["id"]] = logical
            removed.add(value["id"])
    if not replacements:
        return entities
    result: list[dict[str, Any]] = []
    emitted: set[str] = set()
    for entity in entities:
        if entity["id"] in removed:
            logical = merged_by_old[entity["id"]]
            if logical["id"] not in emitted:
                result.append(logical)
                emitted.add(logical["id"])
            continue
        value = dict(entity)
        if value.get("parent_id") in replacements:
            value["parent_id"] = replacements[value["parent_id"]]
        result.append(value)
    return result


def lexical_links(entities: list[dict[str, Any]], sources: dict[str, bytes]) -> list[dict[str, Any]]:
    by_name: dict[str, list[dict[str, Any]]] = {}
    for entity in entities:
        if entity["kind"] != "file" and len(entity["name"]) >= 2:
            by_name.setdefault(entity["name"], []).append(entity)
    links: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for source_entity in entities:
        if source_entity["kind"] == "file":
            continue
        data = sources.get(source_entity["path"], b"")
        region = data[source_entity["range"]["start_byte"] : source_entity["range"]["end_byte"]].decode("utf-8", errors="replace")
        referenced_names = set(re.findall(r"[A-Za-z_$][A-Za-z0-9_$]*", region))
        for name in sorted(referenced_names.intersection(by_name)):
            targets = by_name[name]
            if name == source_entity["name"]:
                continue
            if len(targets) != 1:
                continue
            target = targets[0]
            if target["id"] == source_entity["id"]:
                continue
            key = (source_entity["id"], target["id"], "references")
            if key in seen:
                continue
            seen.add(key)
            links.append({
                "id": stable_id("link", *key),
                "type": "references",
                "source": source_entity["id"],
                "target": target["id"],
                "provider": "tree-sitter-lexical-candidate",
                "evidence": {"name": name, "source_path": source_entity["path"]},
            })
    for entity in entities:
        if entity["parent_id"]:
            key = (entity["parent_id"], entity["id"], "contains")
            links.append({
                "id": stable_id("link", *key),
                "type": "contains",
                "source": entity["parent_id"],
                "target": entity["id"],
                "provider": "tree-sitter",
                "evidence": {"path": entity["path"], "range": entity["range"]},
            })
    return links

