def path_to_uri(path: Path) -> str:
    value = path.resolve().as_posix()
    if os.name == "nt":
        return "file:///" + quote(value, safe="/:@")
    return "file://" + quote(value, safe="/:@")


def uri_to_path(uri: str) -> Path:
    parsed = urlparse(uri)
    value = unquote(parsed.path)
    if os.name == "nt" and value.startswith("/") and len(value) > 2 and value[2] == ":":
        value = value[1:]
    return Path(value).resolve()


class LspClient:
    def __init__(self, command: list[str], cwd: Path, env: dict[str, str] | None = None):
        self.command = command
        self.cwd = cwd
        self.env = env
        self.process: subprocess.Popen[bytes] | None = None
        self._id = 0
        self._messages: "queue.Queue[dict[str, Any]]" = queue.Queue()
        self._pending: dict[int, dict[str, Any]] = {}
        self.transcript: list[dict[str, Any]] = []
        self.stderr: list[str] = []

    def start(self) -> None:
        self.process = subprocess.Popen(
            self.command,
            cwd=str(self.cwd),
            env=self.env,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        threading.Thread(target=self._read_stdout, daemon=True).start()
        threading.Thread(target=self._read_stderr, daemon=True).start()

    def _read_stdout(self) -> None:
        assert self.process and self.process.stdout
        stream = self.process.stdout
        while True:
            headers: dict[str, str] = {}
            while True:
                line = stream.readline()
                if not line:
                    return
                if line in (b"\r\n", b"\n"):
                    break
                key, value = line.decode("ascii", errors="replace").split(":", 1)
                headers[key.lower()] = value.strip()
            length = int(headers.get("content-length", "0"))
            body = stream.read(length)
            if not body:
                return
            message = json.loads(body.decode("utf-8"))
            self.transcript.append({"direction": "in", "message": message})
            self._messages.put(message)

    def _read_stderr(self) -> None:
        assert self.process and self.process.stderr
        for line in iter(self.process.stderr.readline, b""):
            self.stderr.append(line.decode("utf-8", errors="replace").rstrip())

    def send(self, message: dict[str, Any]) -> None:
        assert self.process and self.process.stdin
        body = json.dumps(message, separators=(",", ":")).encode("utf-8")
        header = f"Content-Length: {len(body)}\r\n\r\n".encode("ascii")
        self.transcript.append({"direction": "out", "message": message})
        self.process.stdin.write(header + body)
        self.process.stdin.flush()

    def notify(self, method: str, params: Any) -> None:
        self.send({"jsonrpc": "2.0", "method": method, "params": params})

    def request(self, method: str, params: Any, timeout: int = 60) -> Any:
        self._id += 1
        request_id = self._id
        self.send({"jsonrpc": "2.0", "id": request_id, "method": method, "params": params})
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if request_id in self._pending:
                message = self._pending.pop(request_id)
            else:
                try:
                    message = self._messages.get(timeout=min(0.5, max(0.01, deadline - time.monotonic())))
                except queue.Empty:
                    continue
            if message.get("method") and "id" in message:
                server_method = message.get("method")
                if server_method == "workspace/configuration":
                    items = (message.get("params") or {}).get("items") or []
                    server_result: Any = [{} for _ in items]
                elif server_method in {"client/registerCapability", "client/unregisterCapability", "window/workDoneProgress/create"}:
                    server_result = None
                else:
                    server_result = None
                self.send({"jsonrpc": "2.0", "id": message["id"], "result": server_result})
                continue
            if message.get("id") == request_id:
                if "error" in message:
                    raise CkbError(f"LSP {method} failed: {message['error']}")
                return message.get("result")
            if "id" in message:
                self._pending[int(message["id"])] = message
        raise CkbError(f"LSP request timed out: {method}")

    def stop(self) -> None:
        if not self.process:
            return
        try:
            self.request("shutdown", None, timeout=10)
            self.notify("exit", None)
        except Exception:
            pass
        try:
            self.process.terminate()
            self.process.wait(timeout=5)
        except Exception:
            self.process.kill()


def _provider_spec(language: str, repo: Path, options: dict[str, Any] | None = None) -> tuple[list[str], str, dict[str, Any], str, Path, dict[str, str]]:
    environment = os.environ.copy()
    if language == "python":
        command = resolve_executable("pyright-langserver")
        if not command:
            raise DependencyError("pyright-langserver is required for Python semantic evidence")
        return [command, "--stdio"], "python", {}, "exact", repo, environment
    if language == "javascript":
        command = resolve_executable("typescript-language-server")
        if not command:
            raise DependencyError("typescript-language-server is required for JavaScript semantic evidence")
        command_path = Path(command).resolve()
        node_modules = command_path.parent.parent
        explicit_tsserver = os.environ.get("CKB_TYPESCRIPT_TSSERVER_PATH")
        candidates = [
            Path(explicit_tsserver).expanduser() if explicit_tsserver else None,
            node_modules / "typescript" / "lib" / "tsserver.js",
            command_path.parent / "tsserver" / "node_modules" / "typescript" / "lib" / "tsserver.js",
        ]
        tsserver_path = next((item.resolve() for item in candidates if item and item.is_file()), None)
        initialization = {"tsserver": {"path": str(tsserver_path)}} if tsserver_path else {}
        return [command, "--stdio"], "javascript", initialization, "exact", repo, environment
    if language == "csharp":
        command = resolve_executable("csharp-ls")
        dotnet = resolve_executable("dotnet")
        if not command or not dotnet:
            raise DependencyError("csharp-ls 0.26.0 and .NET 10 SDK are required for C# semantic evidence")
        workspace = (options or {}).get("csharp_workspace") or {}
        workspace_root = Path(workspace.get("workspace_root") or repo).resolve()
        kind = workspace.get("kind", "folder")
        selected = workspace.get("path")
        server_cwd = workspace_root
        command_line = [command, "--loglevel", "warning", "--locale", "en-US"]
        if kind == "solution" and selected:
            command_line.extend(["--solution", selected])
        elif kind in {"project", "fallback-project"} and selected:
            server_cwd = (workspace_root / Path(*PurePosixPath(selected).parent.parts)).resolve()
        dotnet_path = Path(dotnet).resolve()
        if dotnet_path.parent.name.lower() == "dotnet" or (dotnet_path.parent / "host").is_dir():
            environment["DOTNET_ROOT"] = str(dotnet_path.parent)
        restore = workspace.get("restore") or {}
        if restore.get("performed"):
            runtime_root = workspace_root.parent
            environment["NUGET_PACKAGES"] = str((runtime_root / "nuget-packages").resolve())
            environment["DOTNET_CLI_HOME"] = str((runtime_root / "dotnet-home").resolve())
        environment.update({"DOTNET_NOLOGO": "1", "DOTNET_SKIP_FIRST_TIME_EXPERIENCE": "1", "DOTNET_CLI_TELEMETRY_OPTOUT": "1", "DOTNET_CLI_UI_LANGUAGE": "en-US"})
        initialization = {"workspace": workspace, "restoreAllowed": bool(restore.get("requested")), "networkRestorePerformed": bool(restore.get("network_restore"))}
        return command_line, "csharp", initialization, workspace.get("precision", "bounded-approximate"), server_cwd, environment
    command = resolve_executable("clangd")
    if not command:
        raise DependencyError("clangd is required for C/C++ semantic evidence")
    compile_db = None
    for candidate in (repo / "compile_commands.json", repo / "build" / "compile_commands.json"):
        if candidate.is_file():
            compile_db = candidate.parent
            break
    if compile_db:
        return [command, f"--compile-commands-dir={compile_db}", "--log=verbose"], "c" if language == "c" else "cpp", {"compilationDatabasePath": str(compile_db)}, "exact", repo, environment
    flags, evidence = _fallback_flags(repo, language)
    return [command, "--log=verbose"], "c" if language == "c" else "cpp", {"fallbackFlags": flags, "fallbackEvidence": evidence}, "bounded-approximate", repo, environment


def _fallback_flags(repo: Path, language: str) -> tuple[list[str], dict[str, Any]]:
    """Resolve a unique language standard from build files or use the bounded default."""
    candidates: set[str] = set()
    evidence: list[dict[str, str]] = []
    patterns = (
        ((r"CXX_STANDARD\s+([0-9]+)", r"cxx_std_([0-9]+)", r"-std=c\+\+([0-9]+)"), "c++")
        if language == "cpp"
        else ((r"(?<!X)C_STANDARD\s+([0-9]+)", r"c_std_([0-9]+)", r"-std=c([0-9]+)"), "c")
    )
    regexes, prefix = patterns
    build_names = {"CMakeLists.txt", "meson.build", "Makefile", "makefile"}
    paths = [path for path in repo.rglob("*") if path.is_file() and (path.name in build_names or path.suffix.lower() in {".cmake", ".vcxproj", ".mk"})]
    for path in sorted(paths)[:500]:
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        for pattern in regexes:
            for match in re.finditer(pattern, text, flags=re.IGNORECASE):
                value = match.group(1)
                standard = f"{prefix}{value}"
                candidates.add(standard)
                evidence.append({"path": path.relative_to(repo).as_posix(), "match": match.group(0), "standard": standard})
    default_standard = "c17" if language == "c" else "c++17"
    selected = next(iter(candidates)) if len(candidates) == 1 else default_standard
    resolution = "build-config-unique" if len(candidates) == 1 else ("fallback-no-evidence" if not candidates else "fallback-ambiguous-evidence")
    flags = ["-x", "c" if language == "c" else "c++", f"-std={selected}"]
    return flags, {"resolution": resolution, "candidates": sorted(candidates), "matches": evidence, "selected": selected}


def _flatten_symbols(values: Any) -> list[dict[str, Any]]:
    result: list[dict[str, Any]] = []
    if not isinstance(values, list):
        return result
    for item in values:
        if not isinstance(item, dict):
            continue
        result.append(item)
        result.extend(_flatten_symbols(item.get("children")))
    return result


def collect_semantics(
    repo: Path,
    language: str,
    files: list[dict[str, Any]],
    entities: list[dict[str, Any]],
    options: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if os.environ.get("CKB_TEST_PROVIDER") == "deterministic-fixture":
        covered = [e["id"] for e in entities if e["kind"] != "file" and e["language"] == language]
        return {
            "provider": {"name": "deterministic-fixture", "language": language, "status": "passed", "precision": "test-only", "covered_entity_ids": covered},
            "links": [],
            "diagnostics": [],
            "transcript": [],
            "stderr": [],
        }
    command, language_id, initialization, precision, server_cwd, environment = _provider_spec(language, repo, options)
    document_root = Path(((options or {}).get("csharp_workspace") or {}).get("workspace_root") or repo).resolve() if language == "csharp" else repo
    client = LspClient(command, server_cwd, environment)
    client.start()
    diagnostics: list[dict[str, Any]] = []
    symbol_counts: dict[str, int] = {}
    covered: set[str] = set()
    semantic_links: list[dict[str, Any]] = []
    entity_by_position: dict[tuple[str, int], list[dict[str, Any]]] = {}
    for entity in entities:
        entity_by_position.setdefault((entity["path"], entity["range"].get("name_line", entity["range"]["start_line"]) - 1), []).append(entity)
    try:
        result = client.request(
            "initialize",
            {
                "processId": os.getpid(),
                "rootUri": path_to_uri(document_root),
                "workspaceFolders": [{"uri": path_to_uri(document_root), "name": document_root.name}],
                "capabilities": {"workspace": {"configuration": True}, "textDocument": {"documentSymbol": {"hierarchicalDocumentSymbolSupport": True}}},
                "initializationOptions": initialization,
            },
            timeout=90,
        )
        client.notify("initialized", {})
        for file_entry in files:
            path = (document_root / file_entry["path"]).resolve()
            uri = path_to_uri(path)
            text = path.read_text(encoding="utf-8", errors="replace")
            client.notify(
                "textDocument/didOpen",
                {"textDocument": {"uri": uri, "languageId": language_id, "version": 1, "text": text}},
            )
            symbols = client.request("textDocument/documentSymbol", {"textDocument": {"uri": uri}}, timeout=90)
            flat = _flatten_symbols(symbols)
            symbol_counts[file_entry["path"]] = len(flat)
            for item in flat:
                selection = item.get("selectionRange") or item.get("range") or {}
                start = selection.get("start") or {}
                for entity in entity_by_position.get((file_entry["path"], int(start.get("line", -1))), []):
                    if entity["name"] == item.get("name") or entity["name"] in str(item.get("name", "")):
                        covered.add(entity["id"])
            for entity in [e for e in entities if e["path"] == file_entry["path"] and e["kind"] != "file" and e["candidate_classification"] == "page"]:
                position = {"line": entity["range"].get("name_line", entity["range"]["start_line"]) - 1, "character": entity["range"].get("name_column_utf8", 0)}
                try:
                    definitions = client.request("textDocument/definition", {"textDocument": {"uri": uri}, "position": position}, timeout=30)
                    references = client.request("textDocument/references", {"textDocument": {"uri": uri}, "position": position, "context": {"includeDeclaration": False}}, timeout=30)
                except CkbError:
                    definitions, references = [], []
                if definitions:
                    covered.add(entity["id"])
                for location in references or []:
                    target_uri = location.get("uri") or (location.get("targetUri") if isinstance(location, dict) else None)
                    target_range = location.get("range") or location.get("targetSelectionRange") or {}
                    if not target_uri:
                        continue
                    try:
                        rel = uri_to_path(target_uri).relative_to(document_root).as_posix()
                    except ValueError:
                        continue
                    line = int((target_range.get("start") or {}).get("line", -1))
                    for source_entity in entity_by_position.get((rel, line), []):
                        if source_entity["id"] == entity["id"]:
                            continue
                        semantic_links.append({
                            "id": stable_id("link", source_entity["id"], entity["id"], "references", language),
                            "type": "references",
                            "source": source_entity["id"],
                            "target": entity["id"],
                            "provider": command[0],
                            "evidence": {"uri": target_uri, "line": line, "queried_entity": entity["id"]},
                        })
        time.sleep(0.2)
        for event in client.transcript:
            message = event.get("message", {})
            if event.get("direction") == "in" and message.get("method") == "textDocument/publishDiagnostics":
                params = message.get("params", {})
                diagnostics.extend(params.get("diagnostics", []))
        fatal_patterns = (
            "invalid ast",
            "file not found",
            "could not build compilerinvocation",
            "pp_file_not_found",
            "failed to create target",
            "could not be loaded",
            "project file does not exist",
            "assets file",
            "failed to load project",
            "failed to load solution",
        )
        fatal = [d for d in diagnostics if any(p in str(d.get("message", "")).lower() for p in fatal_patterns)]
        fatal_stderr = [line for line in client.stderr if any(pattern in line.lower() for pattern in fatal_patterns)]
        provider = {
            "name": Path(command[0]).name,
            "language": language,
            "command": command,
            "initialization_options": initialization,
            "server_cwd": str(server_cwd),
            "document_root": str(document_root),
            "precision": precision,
            "status": "failed" if fatal or fatal_stderr or any(symbol_counts.get(f["path"], 0) == 0 for f in files) else "passed",
            "covered_entity_ids": sorted(covered),
            "document_symbol_counts": symbol_counts,
            "diagnostic_count": len(diagnostics),
            "fatal_diagnostics": fatal,
            "fatal_stderr": fatal_stderr,
            "capabilities": result.get("capabilities", {}) if isinstance(result, dict) else {},
        }
        return {"provider": provider, "links": semantic_links, "diagnostics": diagnostics, "transcript": client.transcript, "stderr": client.stderr}
    finally:
        client.stop()

from __future__ import annotations

import json
import os
import shutil
import zipfile
from pathlib import Path
from typing import Any

from .common import CkbError, DependencyError, json_load, json_write, safe_rmtree, sha256_file, utc_now
from .providers import private_runtime_root


def skill_root() -> Path:
    return Path(__file__).resolve().parents[2]


def lock_document() -> dict[str, Any]:
    return json_load(skill_root() / "toolchain.lock.json")


def payload_path() -> Path:
    return skill_root() / "assets" / "runtime" / "win-x64" / "payload.zip"


def deployment_plan() -> dict[str, Any]:
    lock = lock_document()
    payload = payload_path()
    destination = private_runtime_root() / lock["lock_id"]
    payload_lock = lock.get("payload")
    deployed_record = (
        json_load(destination / "deployed.json")
        if destination.is_dir() and (destination / "deployed.json").is_file()
        else {}
    )
    required_members = payload_lock.get("required_members", []) if isinstance(payload_lock, dict) else []
    deployment_matches = (
        isinstance(payload_lock, dict)
        and deployed_record.get("status") == "ready"
        and deployed_record.get("lock_id") == lock.get("lock_id")
        and deployed_record.get("payload_sha256") == payload_lock.get("sha256")
        and (destination / "payload-files.json").is_file()
        and isinstance(required_members, list)
        and bool(required_members)
        and all((destination / member).is_file() for member in required_members)
    )
    if deployment_matches:
        status = "ready"
    elif not payload.is_file():
        status = "payload-missing"
    elif not isinstance(payload_lock, dict):
        status = "payload-unlocked"
    elif payload.stat().st_size != int(payload_lock.get("size", -1)) or sha256_file(payload) != payload_lock.get("sha256"):
        status = "payload-invalid"
    else:
        status = "permission-required"
    return {
        "status": status,
        "lock_id": lock["lock_id"],
        "components": lock["components"],
        "payload": str(payload.resolve()),
        "payload_size": payload.stat().st_size if payload.is_file() else None,
        "payload_sha256": sha256_file(payload) if payload.is_file() else None,
        "expected_payload": payload_lock,
        "destination": str(destination.resolve()),
        "rollback": f"runtime remove --lock-id {lock['lock_id']}",
    }


def deploy(accept: bool) -> dict[str, Any]:
    plan = deployment_plan()
    if plan["status"] == "ready":
        return plan
    if plan["status"] != "permission-required":
        raise DependencyError(json.dumps(plan, ensure_ascii=False))
    if not accept:
        raise DependencyError(json.dumps(plan, ensure_ascii=False))
    payload = Path(plan["payload"])
    destination = Path(plan["destination"])
    destination.parent.mkdir(parents=True, exist_ok=True)
    temporary = destination.with_name(destination.name + ".deploying")
    if temporary.exists():
        safe_rmtree(temporary, destination.parent)
    temporary.mkdir()
    host_snapshot = _host_snapshot()
    with zipfile.ZipFile(payload) as archive:
        for member in archive.infolist():
            target = (temporary / member.filename).resolve()
            try:
                target.relative_to(temporary.resolve())
            except ValueError as exc:
                raise CkbError(f"runtime archive path escapes destination: {member.filename}") from exc
        archive.extractall(temporary)
    files_manifest_path = temporary / "payload-files.json"
    if not files_manifest_path.is_file():
        safe_rmtree(temporary, destination.parent)
        raise CkbError("runtime payload lacks payload-files.json")
    files_manifest = json_load(files_manifest_path)
    for item in files_manifest.get("files", []):
        member_path = (temporary / item["path"]).resolve()
        try:
            member_path.relative_to(temporary.resolve())
        except ValueError as exc:
            safe_rmtree(temporary, destination.parent)
            raise CkbError(f"runtime manifest path escapes destination: {item['path']}") from exc
        if not member_path.is_file() or member_path.stat().st_size != int(item["size"]) or sha256_file(member_path) != item["sha256"]:
            safe_rmtree(temporary, destination.parent)
            raise CkbError(f"runtime payload member verification failed: {item['path']}")
    json_write(
        temporary / "deployed.json",
        {
            "status": "ready",
            "lock_id": plan["lock_id"],
            "payload_sha256": plan["payload_sha256"],
            "deployed_at_utc": utc_now(),
            "host_snapshot_before": host_snapshot,
        },
    )
    if destination.exists():
        safe_rmtree(destination, destination.parent)
    os.replace(temporary, destination)
    plan["status"] = "ready"
    return plan


def remove(lock_id: str) -> dict[str, Any]:
    root = private_runtime_root().resolve()
    target = (root / lock_id).resolve()
    try:
        target.relative_to(root)
    except ValueError as exc:
        raise CkbError("runtime lock ID resolves outside the private runtime root") from exc
    existed = target.exists()
    deployment = json_load(target / "deployed.json") if (target / "deployed.json").is_file() else {}
    if existed:
        safe_rmtree(target, root)
    current_snapshot = _host_snapshot()
    expected_snapshot = deployment.get("host_snapshot_before")
    return {
        "status": "removed",
        "lock_id": lock_id,
        "path": str(target),
        "existed": existed,
        "host_snapshot_before": expected_snapshot,
        "host_snapshot_after": current_snapshot,
        "host_environment_restored": expected_snapshot is None or expected_snapshot == current_snapshot,
    }


def _host_snapshot() -> dict[str, Any]:
    commands = ["python", "node", "git", "pyright-langserver", "typescript-language-server", "clangd", "csharp-ls", "dotnet", "logseq"]
    return {"path": os.environ.get("PATH", ""), "commands": {name: shutil.which(name) for name in commands}}

"""Machine-local clickable links for source files and Obsidian notes."""

from __future__ import annotations

import json
import os
from pathlib import Path, PurePosixPath
from typing import Any
from urllib.parse import quote, unquote, urlparse

from .common import CkbError, json_load, json_write, path_inside


SOURCE_EDITORS = {"vscode", "vscode-insiders", "file", "custom-template"}


class SourceLinkRenderer:
    """Validate one opener config and cache resolved repository paths.

    Retrieval may render several entities from the same file.  The public
    one-shot helpers below intentionally preserve their old behavior, while a
    long-lived renderer avoids repeating Windows ``resolve`` and
    ``_getfinalpathname`` work for every candidate.
    """

    def __init__(self, config: dict[str, Any], *, trusted_relative_paths: bool = False) -> None:
        self.config = validate_local_openers(config)
        root_value = self.config.get("working_repo_root")
        if self.config.get("source_view") == "baseline" and self.config.get("baseline_snapshot_root"):
            root_value = self.config["baseline_snapshot_root"]
        self.root = Path(str(root_value)).resolve()
        self.trusted_relative_paths = trusted_relative_paths
        self._absolute_paths: dict[str, Path] = {}

    @property
    def cache_size(self) -> int:
        return len(self._absolute_paths)

    def absolute_path(self, relative_path: str) -> Path:
        cached = self._absolute_paths.get(relative_path)
        if cached is not None:
            return cached
        relative = PurePosixPath(relative_path)
        if relative.is_absolute() or ".." in relative.parts:
            raise CkbError(f"source path is outside the repository: {relative_path}")
        joined = self.root.joinpath(*relative.parts)
        if self.trusted_relative_paths:
            # Machine retrieval only supplies paths from the audited source
            # manifest.  Absolute and parent components were rejected above,
            # so the lexical path is repository-bounded without another
            # filesystem canonicalization for every selected entity.
            path = joined
        else:
            path = joined.resolve()
            if not path_inside(path, self.root):
                raise CkbError(f"source path is outside the selected source root: {relative_path}")
        self._absolute_paths[relative_path] = path
        return path

    def uri(self, relative_path: str, line: int, column: int = 1) -> str:
        absolute = self.absolute_path(relative_path)
        encoded = quote(absolute.as_posix(), safe="/:")
        editor = self.config["source_editor"]
        if editor == "vscode":
            return f"vscode://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "vscode-insiders":
            return f"vscode-insiders://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "file":
            prefix = "file:///" if os.name == "nt" else "file://"
            return prefix + encoded
        return str(self.config["custom_template"]).format(
            absolute_path=encoded,
            line=int(line),
            column=int(column),
        )

    def markdown_link(self, relative_path: str, start_line: int, end_line: int) -> str:
        uri = self.uri(relative_path, start_line, 1)
        label = f"打开源码：{relative_path} 第 {start_line} 行"
        suffix = f"  `{relative_path}:{start_line}-{end_line}`" if self.config.get("show_source_range", True) else ""
        return f"[{label}]({uri}){suffix}"


def default_openers(repository_root: Path, snapshot_root: Path | None = None) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "source_editor": "vscode" if os.name == "nt" else "file",
        "working_repo_root": str(repository_root.resolve()),
        "baseline_snapshot_root": str(snapshot_root.resolve()) if snapshot_root else None,
        "source_view": "working",
        "show_source_range": True,
        "custom_template": None,
    }


def ensure_local_openers(output: Path, repository_root: Path, snapshot_root: Path | None = None) -> dict[str, Any]:
    path = output / "local-openers.json"
    if path.is_file():
        return validate_local_openers(json_load(path))
    value = default_openers(repository_root, snapshot_root)
    json_write(path, value)
    return value


def validate_local_openers(value: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(value, dict) or value.get("schema_version") != 1:
        raise CkbError("local-openers.json must use schema_version 1")
    editor = value.get("source_editor")
    if editor not in SOURCE_EDITORS:
        raise CkbError(f"unsupported source editor: {editor}")
    root = Path(str(value.get("working_repo_root", ""))).resolve()
    if not root.is_dir():
        raise CkbError(f"working repository root is missing: {root}")
    source_view = value.get("source_view", "working")
    if source_view not in {"working", "baseline"}:
        raise CkbError("source_view must be working or baseline")
    template = value.get("custom_template")
    if editor == "custom-template" and (
        not isinstance(template, str)
        or "{absolute_path}" not in template
        or "{line}" not in template
        or "{column}" not in template
    ):
        raise CkbError("custom source-link template requires {absolute_path}, {line}, and {column}")
    return {
        "schema_version": 1,
        "source_editor": editor,
        "working_repo_root": str(root),
        "baseline_snapshot_root": value.get("baseline_snapshot_root"),
        "source_view": source_view,
        "show_source_range": bool(value.get("show_source_range", True)),
        "custom_template": template,
    }


def update_local_openers(
    output: Path,
    repository_root: Path,
    *,
    editor: str = "vscode",
    source_view: str = "working",
    custom_template: str | None = None,
) -> dict[str, Any]:
    state_path = output / "state.json"
    if not state_path.is_file():
        raise CkbError(f"state.json does not exist: {state_path}")
    state = json_load(state_path)
    snapshot_root = (state.get("source_snapshot") or {}).get("root")
    value = default_openers(repository_root, Path(snapshot_root) if snapshot_root else None)
    value.update({"source_editor": editor, "source_view": source_view, "custom_template": custom_template})
    value = validate_local_openers(value)
    json_write(output / "local-openers.json", value)
    return value


def source_absolute_path(config: dict[str, Any], relative_path: str) -> Path:
    return SourceLinkRenderer(config).absolute_path(relative_path)


def source_uri(config: dict[str, Any], relative_path: str, line: int, column: int = 1) -> str:
    return SourceLinkRenderer(config).uri(relative_path, line, column)


def source_markdown_link(config: dict[str, Any], relative_path: str, start_line: int, end_line: int) -> str:
    return SourceLinkRenderer(config).markdown_link(relative_path, start_line, end_line)


def obsidian_open_uri(path: Path) -> str:
    return "obsidian://open?path=" + quote(str(path.resolve()), safe="")


def audit_source_uri(config: dict[str, Any], uri: str, relative_path: str, line: int) -> str | None:
    expected = source_uri(config, relative_path, line, 1)
    if uri != expected:
        return "source-uri-does-not-match-source-location"
    parsed = urlparse(uri)
    if parsed.scheme not in {"vscode", "vscode-insiders", "file", "cursor", "idea"}:
        return "source-uri-scheme-is-not-allowed"
    if parsed.scheme.startswith("vscode"):
        decoded = unquote(parsed.path)
        if f":{int(line)}:1" not in decoded:
            return "source-uri-line-is-missing"
    return None

#!/usr/bin/env python3
"""Create reproducible lite/full Skill archives after validating locked inputs."""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
import zipfile
from pathlib import Path, PurePosixPath


VERSION = "5.1.3"
ROOT = Path(__file__).resolve().parents[1]
EXCLUDED_PARTS = {".git", "__pycache__", ".pytest_cache", ".mypy_cache"}


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_files(include_runtime: bool) -> list[Path]:
    result: list[Path] = []
    for path in ROOT.rglob("*"):
        if not path.is_file() or any(part in EXCLUDED_PARTS for part in path.parts):
            continue
        relative = path.relative_to(ROOT)
        if not include_runtime and relative.parts[:3] == ("assets", "runtime", "win-x64"):
            continue
        if path.suffix in {".pyc", ".pyo"}:
            continue
        result.append(path)
    return sorted(result, key=lambda item: item.relative_to(ROOT).as_posix())


def validate_full_payload(lock: dict) -> Path:
    payload_lock = lock.get("payload")
    if not isinstance(payload_lock, dict):
        raise RuntimeError("full payload lock is pending")
    relative = payload_lock.get("path")
    if not isinstance(relative, str):
        raise RuntimeError("full payload path is absent from the lock")
    path = (ROOT / relative).resolve()
    if not path.is_file():
        raise RuntimeError(f"full payload is absent: {path}")
    if path.stat().st_size != int(payload_lock.get("size", -1)):
        raise RuntimeError("full payload size differs from toolchain.lock.json")
    actual_hash = sha256(path)
    if actual_hash != payload_lock.get("sha256"):
        raise RuntimeError("full payload SHA-256 differs from toolchain.lock.json")
    for required in payload_lock.get("required_members", []):
        with zipfile.ZipFile(path) as archive:
            if required not in archive.namelist():
                raise RuntimeError(f"full payload member is absent: {required}")
    return path


def build(kind: str, dist: Path) -> dict:
    lock = json.loads((ROOT / "toolchain.lock.json").read_text(encoding="utf-8"))
    include_runtime = kind == "full-win-x64"
    if include_runtime:
        validate_full_payload(lock)
    files = source_files(include_runtime)
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder",
        "version": VERSION,
        "distribution": kind,
        "toolchain_lock_id": lock["lock_id"],
        "files": [
            {
                "path": path.relative_to(ROOT).as_posix(),
                "size": path.stat().st_size,
                "sha256": sha256(path),
            }
            for path in files
        ],
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-{kind}-{VERSION}.zip"
    if archive_path.exists():
        archive_path.unlink()
    prefix = PurePosixPath("code-knowledge-builder")
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            relative = PurePosixPath(path.relative_to(ROOT).as_posix())
            info = zipfile.ZipInfo(str(prefix / relative), date_time=(2026, 8, 26, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
        manifest_info = zipfile.ZipInfo(str(prefix / "distribution" / "release-manifest.json"), date_time=(2026, 8, 26, 0, 0, 0))
        manifest_info.compress_type = zipfile.ZIP_DEFLATED
        manifest_info.external_attr = 0o100644 << 16
        archive.writestr(manifest_info, json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8") + b"\n")
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"ZIP CRC failed: {bad_member}")
        archived_manifest = json.loads(archive.read(str(prefix / "distribution" / "release-manifest.json")))
        if archived_manifest != manifest:
            raise RuntimeError("archived release manifest differs from the generated manifest")
    result = {
        "status": "passed",
        "distribution": kind,
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-{kind}-{VERSION}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--kind", choices=("lite", "full-win-x64", "both"), required=True)
    parser.add_argument("--dist", type=Path, required=True)
    args = parser.parse_args()
    kinds = ("lite", "full-win-x64") if args.kind == "both" else (args.kind,)
    results = []
    try:
        for kind in kinds:
            results.append(build(kind, args.dist.resolve()))
    except RuntimeError as exc:
        print(json.dumps({"status": "pending", "reason": str(exc), "completed": results}, ensure_ascii=False, indent=2), file=sys.stderr)
        return 3
    print(json.dumps({"status": "passed", "results": results}, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
